#include <iostream>
#include <map>
#include <string>

void Update(std::map<std::string, int>& stock) {
  if (stock.contains("tea")) {
    stock.insert_or_assign("tea", stock.at("tea") + 1);
  }
  stock.try_emplace("tea", 8);
  std::cout << stock.at("tea") << ' ' << stock.size();
}

int main() {
  std::map<std::string, int> a{{"tea", 2}};
  std::map<std::string, int> b{{"coffee", 5}};
  Update(a);
  std::cout << ' ';
  Update(b);
}
